<?php $title=$session['session_type'];$grouped=[];foreach($session['rows'] as $row)$grouped[$row['workout_exercise_id']][]=$row; ?>
<div class="mb-6 flex items-start justify-between"><div><p class="text-sm text-emerald-500"><?= e(date('M j, Y · H:i',strtotime($session['performed_at']))) ?></p><h1 class="text-3xl font-black"><?= e($session['session_type']) ?></h1><?php if($session['body_weight_kg']): ?><p class="text-zinc-400">Body weight: <?= e($session['body_weight_kg']) ?> kg</p><?php endif; ?></div><a class="btn-secondary" href="<?= e(route('workouts.edit',['id'=>$session['id']])) ?>">Edit</a></div>
<?php if($session['notes']): ?><div class="card mb-4"><?= nl2br(e($session['notes'])) ?></div><?php endif; ?>
<div class="space-y-4"><?php foreach($grouped as $rows): ?><section class="card"><h2 class="mb-3 text-lg font-bold"><?= e($rows[0]['name']) ?></h2><div class="overflow-x-auto"><table><thead><tr><th>#</th><th>Type</th><th>Performance</th></tr></thead><tbody><?php foreach($rows as $row):if(!$row['id'])continue;$segments=$row['segments']??[];?><tr><td><?= (int)$row['position'] ?></td><td><?= e(['warmup'=>'Warm-up','ramp'=>'Ramp-up','working'=>'Working'][$row['set_type']]) ?></td><td><?php if(count($segments)>1): ?><span class="font-semibold text-orange-300">Drop set · </span><?php foreach($segments as $index=>$segment): ?><?= $index?' → ':'' ?><?= e($segment['weight_kg']) ?> kg × <?= (int)$segment['repetitions'] ?><?= (int)$segment['is_personal_record']===1?' 🏆':'' ?><?php endforeach; ?><?php else: ?><?= e($row['weight_kg']??'—') ?> kg × <?= e($row['repetitions']??'—') ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?></div>
<form method="post" action="<?= e(route('workouts.destroy',['id'=>$session['id']])) ?>" class="mt-6" data-confirm="Permanently delete this workout and all its sets?"><?= csrf_field() ?><button class="btn-danger">Delete workout</button></form>
